The button is clicked once. What does it show?

```jsx
function reducer(state, action) {
  switch (action.type) {
    case "inc":
      return state + 1;
    default:
      return state;
  }
}

function Counter() {
  const [count, dispatch] = useReducer(reducer, 0);
  return <button onClick={() => dispatch({ type: "inc" })}>{count}</button>;
}
```

