function reducer(s, a) {
  if (a.type === "add") return s + a.value;
  return s;
}

function Total() {
  const [n, dispatch] = useReducer(reducer, 10);
  return <button onClick={() => dispatch({ type: "add", value: 5 })}>{n}</button>;
}
